import sys

def marsExploration(s):
    count = 0
    expected = "SOS" * (len(s) // 3)
    for i in range(len(s)):
        if s[i] != expected[i]:
            count += 1
    return count

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    result = marsExploration(s)
    print(result)
